# DK SBT.  Sønderborg - Tønder
#
let st = path("d3.dk.sbt");

with detail = 4, railway = :first :cat:ac25 :pax {
    with link = "point.dk.Sønderborg", railway = :station {
        track(st[:son.a, :son + 0.5sw]);
        marker(:right :de.bf, st[:son] >> 0.5mt);
        station(:top, st[:son] >> 0.5mt >> 1sh + (2dt, -0.8dt),
            hbox(:center:base :former, "Sonderburg", span(:light, " Stsbf")),
            span(:bold, "Sønderborg"),
            hbox(:center:top,
                vbox(:right:top, "SBT: ", " ", span(:removed, "SMM: ")),
                vbox(:sep:top,
                    hbox(:sep:base, "0,", anchor(), "000"),
                    hbox(:sep:base :former, "(39,", anchor(), "28)"),
                    hbox(:sep:base :removed, "0,", anchor(), "0")
                )
            )
        );
    }

    with link = "line.dk.SBT" {
        track(st[:son + 0.49sw, :son + 1.61km]);
        line_label(:left:ne, st[:son + 1.6km] << 0.5mt, "SBT");
        track(st[:son + 1.59km, :rag - 0.49sw]);
    }

    with link = "point.dk.Ragebøl", railway = :station {
        track(st[:rag - 0.5sw, :rag + 0.5sw]);
        marker(:right :de.hp :removed, st[:rag] >> 0.5mt);
        marker(:right :de.exbf :removed, st[:rag] >> 0.5mt);
        station(:right:left_align :removed,
            st[:rag] >> 0.5mt >> 1.4sh + (2.2dt, 0.8dt),
            span(:former, "Rackebüll"),
            "Ragebøl",
            hbox(:left:base, " SBT: ?? ", span(:former, "(35,45)"))
        );
    }

    with link = "line.dk.SBT" {
        track(st[:rag + 0.49sw, :vso.ys - 0.49seg]);
    }

    with link = "point.dk.Vester-Sottrup", railway = :station {
        track(:removed,
                st[:vso.ys, :vso + 380m - 1dl] << 1mo
            --  st[:vso + 380m, :vso + 381m]
        );
        track(st[:vso.ys - 0.5seg, :vso + 400m]);
        marker(:right :de.hp :removed, st[:vso] >> 0.5mt);
        marker(:right :de.exbf :removed, st[:vso] >> 0.5mt);
        station(:top :removed, st[:vso] >> 0.5mt >> 1.4sh + (2dt, -1dt),
            span(:former, "Wester-Satrup"),
            span(:bold, "Vester Sottrup"),
            hbox(:center:top,
                vbox(:right:top, "SBT: ", "VSS: "),
                vbox(:sep:top,
                    hbox(:sep:base,
                        "?", anchor(), "? ", span(:former, "(32,65)")
                    ),
                    hbox(:sep:base, "0,", anchor(), "0")
                )
            )
        );
    }

    with link = "line.dk.SBT" {
        track(st[:vso + 399m, :avn - 0.49sw]);
    }

    with link = "point.dk.Avnbøl", railway = :station {
        track(st[:avn - 0.5sw, :avn + 0.5sw]);
        marker(:left :de.hp :removed, st[:avn] << 0.5mt);
        marker(:left :de.exbf :removed, st[:avn] << 0.5mt);
        station(:bottom :removed, st[:avn] << 0.5mt << 1.4sh << 0.8dt,
            span(:former, "Auenbüll"),
            "Avnbøl",
            "SBT: ??"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:avn + 0.49sw, :ads - 0.49sw]);
    }

    with link = "point.dk.Adsbøl", railway = :station {
        track(st[:ads - 0.5sw, :ads + 0.5sw]);
        marker(:left :de.hp :removed, st[:ads] << 0.5mt);
        station(:right :removed, st[:ads] << 0.5mt << 1sh + (1.8dt, 1.3dt),
            hbox(:left:base, " ", span(:former, "Atzbüll")),
            "Adsbøl",
            "SBT: ??"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:ads + 0.49sw, :gra.ya - 0.49seg]);
        track(:ror, st[:gra.ya - 0.5seg, :gra.ya]);
        track(:ror, st[:gra.ya, :gra.ya + 0.91km]);
        line_label(:left:nw, st[:gra.ya + 0.9km] << 0.5mt, "SBT");
        track(:ror, st[:gra.ya + 0.89km, :gra - 0.49sw]);
    }

    with link = "point.dk.Gråsten", railway = :station {
        track(st[:gra - 0.5sw, :gra + 250m]);
        track(:removed, st[:gra - 0.5sw, :gra + 250m] >> 1mo);
        marker(:right :de.bf, st[:gra] >> 1mo >> 0.5mt);
        station(:left:right_align,
            st[:gra] >> 1mo >> 0.5mt >> 1sh + (-2.3dt, 0.3dt),
            span(:former, "Gravenstein"),
            span(:bold, "Gråsten"),
            hbox(:center:top,
                vbox(:right:top, span(:removed, "ARG: "), "SBT: "),
                vbox(:sep:top,
                    hbox(:sep:base :removed, "31,", anchor(), "5"),
                    hbox(:sep:base, "16,", anchor(), "264 ")
                )
            )
        );
    }

    with link = "line.dk.SBT" {
        track(st[:gra + 249m, :gra + 1.91km]);
        line_label(:right:se, st[:gra + 1.9km] >> 0.5mt, "SBT");
        track(st[:gra + 1.89km, :rin - 0.49sw]);
    }

    with link = "point.dk.Rinkenæs", railway = :station {
        track(st[:rin - 0.5sw, :rin + 0.5sw]);
        marker(:left :de.hp :removed, st[:rin] << 0.5mt);
        marker(:left :de.exbf :removed, st[:rin] << 0.5mt);
        station(:right :removed, st[:rin] << 0.5mt << 1.4sh + (2dt, 2dt),
            hbox(:left:base, " ", span(:former, "Rinkenis")),
            "Rinkenæs", "SBT: ??"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:rin + 0.49sw, :tor - 1.59km]);
        line_label(:right:sw, st[:tor - 1.6km] >> 0.5mt, "SBT");
        track(st[:tor - 1.61km, :tor - 0.49sw]);
    }

    with link = "point.dk.Tørsbøl", railway = :station {
        track(:removed,
               st[:tor + 79m, :tor + 80m] 
            -- st[:tor + 80m + 1dl, :tor.yp] << 1mo
        );
        track(st[:tor - 0.5sw, :tor.yp + 0.5seg]);
        marker(:left :de.hp :removed, st[:tor] << 0.5mt);
        marker(:left :de.exbf :removed, st[:tor] << 0.5mt);
        station(:bottom :removed,
            st[:tor] << 0.5mt << 1.4sh + (-2.5dt, 1.5dt),
            span(:former, "Törsbüll"),
            span(:bold, "Tørsbøl"),
            hbox(:center:top,
                vbox(:right:top, "SBT: ", "TBP: "),
                vbox(:sep:top,
                    hbox(:sep:base, "?", anchor(), "?"),
                    hbox(:sep:base, "0,", anchor(), "0")
                )
            )
        );
    }

    with link = "line.dk.SBT" {
        track(st[:tor.yp + 0.49seg, :tor.yp + 1.01km]);
        line_label(:right:sw, st[:tor.yp + 1km] >> 0.5mt, "SBT");
        track(st[:tor.yp + 0.99km, :lun - 0.49sw]);
    }

    with link = "point.dk.Lundtoft", railway = :station {
        track(st[:lun - 0.5sw, :lun + 0.5sw]);
        marker(:left :de.hp :removed, st[:lun] << 0.5mt);
        station(:bottom :removed, st[:lun] << 0.5mt << 1sh + (-1.5dt, 1dt),
            "Lundtoft", "SBT: ??"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:lun + 0.49sw, :kli - 0.49sw]);
    }

    with link = "point.dk.Kliplev", railway = :station {
        track(st[:kli - 0.5sw, :kli + 0.5sw]);
        marker(:right :de.hp, st[:kli] >> 0.5mt);
        station(:top, st[:kli] >> 0.5mt >> 1sh >> 0.8dt,
            span(:former, "Klipleff"),
            "Kliplev",
            "SBT: 31,300"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:kli + 0.49sw, :bje - 0.49sw]);
    }

    with link = "point.dk.Bjerndrup", railway = :station {
        track(st[:bje - 0.5sw, :bje + 0.5sw]);
        marker(:right :de.hp :removed, st[:bje] >> 0.5mt);
        station(:top :removed, st[:bje] >> 0.5mt >> 1sh >> 0.6dt,
            span(:former, "Behrendorf"),
            "Bjerndrup",
            "SBT: ??"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:bje + 0.49sw, :bje + 2.51km]);
        line_label(:left:n, st[:bje + 2.5km] << 0.5mt, "SBT");
        track(st[:bje + 2.49km, :tin.xs]);
    }
}

with detail = 4, railway = :first :expax :suspended {
    with link = "line.dk.SBT" {
        track(st[:tin.yt + 400m, :tin.yt + 1.51km]);
        line_label(:right:s, st[:tin.yt + 1.5km] >> 0.5mt, "SBT");
        track(st[:tin.yt + 1.49km, :ter - 0.49sw]);
    }

    with link = "point.dk.Terkelsbøl", railway = :station {
        track(st[:ter - 0.5sw, :ter + 0.5sw]);
        marker(:left :de.hp, st[:ter] << 0.5mt);
        marker(:left :de.exbf, st[:ter] << 0.5mt);
        station(:bottom, st[:ter] << 0.5mt << 1.4sh << 0.8dt,
            span(:former, "Terkelsbüll"),
            "Terkelsbøl",
            "SBT: ??"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:ter + 0.49sw, :byl - 0.49sw]);
    }

    with link = "point.dk.Bylderup-Bov", railway = :station {
        track(st[:byl - 0.5sw, :byl + 0.5sw]);
        marker(:left :de.bf, st[:byl] << 0.5mt);
        station(:bottom, st[:byl] << 0.5mt << 1sh << 0.8dt,
            span(:former, "Bülderup-Bau"),
            "Bylderup-Bov",
            "SBT: ??"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:byl + 0.49sw, :jej - 0.49sw]);
    }

    with link = "point.dk.Jejsing", railway = :station {
        track(st[:jej - 0.5sw, :jej + 0.5sw]);
        marker(:left :de.hp, st[:jej] << 0.5mt);
        marker(:left :de.exbf, st[:jej] << 0.5mt);
        station(:bottom, st[:jej] << 0.5mt << 1.4sh << 0.8dt,
            span(:former, "Jeising-Hostrup"),
            "Jejsing",
            "SBT: ??"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:jej + 0.49sw, :ror - 0.49sw]);
    }

    with link = "point.dk.Rørkær", railway = :station {
        track(st[:ror - 0.5sw, :ror + 0.5sw]);
        marker(:left :de.hp :removed, st[:ror] << 0.5mt);
        station(:bottom :removed, st[:ror] << 0.5mt << 1sh << 0.7dt,
            span(:former, "Rohrkarr"),
            "Rørkær",
            "SBT: ??"
        );
    }

    with link = "line.dk.SBT" {
        track(st[:ror + 0.49sw, :too - 0.49sw]);
    }

    with link = "point.dk.Tønder-Øst", railway = :station {
        track(st[:too - 0.5sw, :too + 0.5sw]);
        marker(:left :de.bf, st[:too] << 0.5mt);
        station(:top, st[:too] >> 0.5mt >> 1.3dt,
            vbox(:center:base,
                span(:former, "Tondern Nord"),
                span(:former, "Tønder Nord")
            ),
            "Tønder Øst",
            "SBT: ??"
        );
    }

    with link = "line.dk.SBT" {
        track(:ror,
                st[:too + 0.49sw, :ton.xt]
            ..  st[:ton.yt, :ton.yt + 0.1dl] << 1mo
        );
    }

    # point.dk.Tønder  dk.BTR
}

